@lru_cache
def _load_toml(path: Path | str) -> dict[str, Any]:
    with open(path, "rb") as f:
        return tomllib.load(f)


@lru_cache
def _cached_resolve(path: Path) -> Path:
    return path.resolve()


def find_project_root(
    srcs: Sequence[str | Path], stdin_filename: str | None = None
) -> tuple[Path, str]:
    """Return a directory containing .git, .hg, or pyproject.toml.

    pyproject.toml files are only considered if they contain a [tool.black]
    section and are ignored otherwise.

    That directory will be a common parent of all files and directories
    passed in `srcs`.

    If no directory in the tree contains a marker that would specify it's the
    project root, the root of the file system is returned.

    Returns a two-tuple with the first element as the project root path and
    the second element as a string describing the method by which the
    project root was discovered.
    """
    if stdin_filename is not None:
        srcs = tuple(stdin_filename if s == "-" else s for s in srcs)

    if not srcs:
        resolved_srcs: tuple[str, ...] = (str(_cached_resolve(Path.cwd())),)
    else:
        resolved_srcs = tuple(
            str(_cached_resolve(Path(Path.cwd(), src))) for src in srcs
        )

    return _find_project_root_cached(resolved_srcs)


@lru_cache
def _find_project_root_cached(srcs: tuple[str, ...]) -> tuple[Path, str]:
    path_srcs = [Path(src) for src in srcs]

    # A list of lists of parents for each 'src'. 'src' is included as a
    # "parent" of itself if it is a directory
    src_parents = [
        list(path.parents) + ([path] if path.is_dir() else []) for path in path_srcs
    ]

    common_base = max(
        set.intersection(*(set(parents) for parents in src_parents)),
        key=lambda path: path.parts,
    )

    for directory in (common_base, *common_base.parents):
        if (directory / ".git").exists():
            return directory, ".git directory"

        if (directory / ".hg").is_dir():
            return directory, ".hg directory"

        if (directory / "pyproject.toml").is_file():
            pyproject_toml = _load_toml(directory / "pyproject.toml")
            if "black" in pyproject_toml.get("tool", {}):
                return directory, "pyproject.toml"

    return directory, "file system root"


def find_pyproject_toml(
    path_search_start: tuple[str, ...], stdin_filename: str | None = None
) -> str | None:
    """Find the absolute filepath to a pyproject.toml if it exists"""
    path_project_root, _ = find_project_root(path_search_start, stdin_filename)
    path_pyproject_toml = path_project_root / "pyproject.toml"
    if path_pyproject_toml.is_file():
        return str(path_pyproject_toml)

    try:
        path_user_pyproject_toml = find_user_pyproject_toml()
        return (
            str(path_user_pyproject_toml)
            if path_user_pyproject_toml.is_file()
            else None
        )
    except (PermissionError, RuntimeError) as e:
        # We do not have access to the user-level config directory, so ignore it.
        err(f"Ignoring user configuration directory due to {e!r}")
        return None


@mypyc_attr(patchable=True)
def parse_pyproject_toml(path_config: str) -> dict[str, Any]:
    """Parse a pyproject toml file, pulling out relevant parts for Black.

    If parsing fails, will raise a tomllib.TOMLDecodeError.
    """
    pyproject_toml = _load_toml(path_config)
    config: dict[str, Any] = pyproject_toml.get("tool", {}).get("black", {})
    config = {k.replace("--", "").replace("-", "_"): v for k, v in config.items()}

    if "target_version" not in config:
        inferred_target_version = infer_target_version(pyproject_toml)
        if inferred_target_version is not None:
            config["target_version"] = [v.name.lower() for v in inferred_target_version]

    return config


def infer_target_version(
    pyproject_toml: dict[str, Any],
) -> list[TargetVersion] | None:
    """Infer Black's target version from the project metadata in pyproject.toml.

    Supports the PyPA standard format (PEP 621):
    https://packaging.python.org/en/latest/specifications/declaring-project-metadata/#requires-python

    If the target version cannot be inferred, returns None.
    """
    project_metadata = pyproject_toml.get("project", {})
    requires_python = project_metadata.get("requires-python", None)
    if requires_python is not None:
        try:
            return parse_req_python_version(requires_python)
        except InvalidVersion:
            pass
        try:
            return parse_req_python_specifier(requires_python)
        except (InvalidSpecifier, InvalidVersion):
            pass

    return None


def parse_req_python_version(requires_python: str) -> list[TargetVersion] | None:
    """Parse a version string (i.e. ``"3.7"``) to a list of TargetVersion.

    If parsing fails, will raise a packaging.version.InvalidVersion error.
    If the parsed version cannot be mapped to a valid TargetVersion, returns None.
    """
    version = Version(requires_python)
    if version.release[0] != 3:
        return None
    try:
        return [TargetVersion(version.release[1])]
    except (IndexError, ValueError):
        return None


def parse_req_python_specifier(requires_python: str) -> list[TargetVersion] | None:
    """Parse a specifier string (i.e. ``">=3.7,<3.10"``) to a list of TargetVersion.

    If parsing fails, will raise a packaging.specifiers.InvalidSpecifier error.
    If the parsed specifier cannot be mapped to a valid TargetVersion, returns None.
    """
    specifier_set = strip_specifier_set(SpecifierSet(requires_python))
    if not specifier_set:
        return None

    target_version_map = {f"3.{v.value}": v for v in TargetVersion}
    compatible_versions: list[str] = list(specifier_set.filter(target_version_map))
    if compatible_versions:
        return [target_version_map[v] for v in compatible_versions]
    return None


def strip_specifier_set(specifier_set: SpecifierSet) -> SpecifierSet:
    """Strip minor versions for some specifiers in the specifier set.

    For background on version specifiers, see PEP 440:
    https://peps.python.org/pep-0440/#version-specifiers
    """
    specifiers = []
    for s in specifier_set:
        if "*" in str(s):
            specifiers.append(s)
        elif s.operator in ["~=", "==", ">=", "==="]:
            version = Version(s.version)
            stripped = Specifier(f"{s.operator}{version.major}.{version.minor}")
            specifiers.append(stripped)
        elif s.operator == ">":
            version = Version(s.version)
            if len(version.release) > 2:
                s = Specifier(f">={version.major}.{version.minor}")
            specifiers.append(s)
        else:
            specifiers.append(s)

    return SpecifierSet(",".join(str(s) for s in specifiers))


@lru_cache
def find_user_pyproject_toml() -> Path:
    r"""Return the path to the top-level user configuration for black.

    This looks for ~\.black on Windows and ~/.config/black on Linux and other
    Unix systems.

    May raise:
    - RuntimeError: if the current user has no homedir
    - PermissionError: if the current process cannot access the user's homedir
    """
    if sys.platform == "win32":
        # Windows
        user_config_path = Path.home() / ".black"
    else:
        config_root = os.environ.get("XDG_CONFIG_HOME", "~/.config")
        user_config_path = Path(config_root).expanduser() / "black"
    return _cached_resolve(user_config_path)


@lru_cache
def get_gitignore(root: Path) -> GitIgnoreSpec:
    """Return a GitIgnoreSpec matching gitignore content if present."""
    gitignore = root / ".gitignore"
    lines: list[str] = []
    if gitignore.is_file():
        with gitignore.open(encoding="utf-8") as gf:
            lines = gf.readlines()
    try:
        return GitIgnoreSpec.from_lines(lines)
    except GitIgnorePatternError as e:
        err(f"Could not parse {gitignore}: {e}")
        raise


def resolves_outside_root_or_cannot_stat(
    path: Path,
    root: Path,
    report: Report | None = None,
) -> bool:
    """
    Returns whether the path is a symbolic link that points outside the
    root directory. Also returns True if we failed to resolve the path.
    """
    try:
        resolved_path = _cached_resolve(path)
    except OSError as e:
        if report:
            report.path_ignored(path, f"cannot be read because {e}")
        return True
    try:
        resolved_path.relative_to(root)
    except ValueError:
        if report:
            report.path_ignored(path, f"is a symbolic link that points outside {root}")
        return True
    return False


def best_effort_relative_path(path: Path, root: Path) -> Path:
    # Precondition: resolves_outside_root_or_cannot_stat(path, root) is False
    try:
        return path.absolute().relative_to(root)
    except ValueError:
        pass
    root_parent = next((p for p in path.parents if _cached_resolve(p) == root), None)
    if root_parent is not None:
        return path.relative_to(root_parent)
    # something adversarial, fallback to path guaranteed by precondition
    return _cached_resolve(path).relative_to(root)


def _path_is_ignored(
    root_relative_path: str,
    root: Path,
    gitignore_dict: dict[Path, GitIgnoreSpec],
) -> bool:
    path = root / root_relative_path
    # Note that this logic is sensitive to the ordering of gitignore_dict. Callers must
    # ensure that gitignore_dict is ordered from least specific to most specific.
    for gitignore_path, pattern in gitignore_dict.items():
        try:
            relative_path = path.relative_to(gitignore_path).as_posix()
            if path.is_dir():
                relative_path = relative_path + "/"
        except ValueError:
            break
        if pattern.match_file(relative_path):
            return True
    return False


def path_is_excluded(
    normalized_path: str,
    pattern: Pattern[str] | None,
) -> bool:
    match = pattern.search(normalized_path) if pattern else None
    return bool(match and match.group(0))


def gen_python_files(
    paths: Iterable[Path],
    root: Path,
    include: Pattern[str],
    exclude: Pattern[str],
    extend_exclude: Pattern[str] | None,
    force_exclude: Pattern[str] | None,
    report: Report,
    gitignore_dict: dict[Path, GitIgnoreSpec] | None,
    *,
    verbose: bool,
    quiet: bool,
) -> Iterator[Path]:
    """Generate all files under `path` whose paths are not excluded by the
    `exclude_regex`, `extend_exclude`, or `force_exclude` regexes,
    but are included by the `include` regex.

    Symbolic links pointing outside of the `root` directory are ignored.

    `report` is where output about exclusions goes.
    """

    assert root.is_absolute(), f"INTERNAL ERROR: `root` must be absolute but is {root}"
    for child in paths:
        assert child.is_absolute()
        root_relative_path = child.relative_to(root).as_posix()

        # First ignore files matching .gitignore, if passed
        if gitignore_dict and _path_is_ignored(
            root_relative_path, root, gitignore_dict
        ):
            report.path_ignored(child, "matches a .gitignore file content")
            continue

        # Then ignore with `--exclude` `--extend-exclude` and `--force-exclude` options.
        root_relative_path = "/" + root_relative_path
        if child.is_dir():
            root_relative_path += "/"

        if path_is_excluded(root_relative_path, exclude):
            report.path_ignored(child, "matches the --exclude regular expression")
            continue

        if path_is_excluded(root_relative_path, extend_exclude):
            report.path_ignored(
                child, "matches the --extend-exclude regular expression"
            )
            continue

        if path_is_excluded(root_relative_path, force_exclude):
            report.path_ignored(child, "matches the --force-exclude regular expression")
            continue

        if resolves_outside_root_or_cannot_stat(child, root, report):
            continue

        if child.is_dir():
            # If gitignore is None, gitignore usage is disabled, while a Falsey
            # gitignore is when the directory doesn't have a .gitignore file.
            if gitignore_dict is not None:
                new_gitignore_dict = {
                    **gitignore_dict,
                    root / child: get_gitignore(child),
                }
            else:
                new_gitignore_dict = None
            yield from gen_python_files(
                child.iterdir(),
                root,
                include,
                exclude,
                extend_exclude,
                force_exclude,
                report,
                new_gitignore_dict,
                verbose=verbose,
                quiet=quiet,
            )

        elif child.is_file():
            if child.suffix == ".ipynb" and not jupyter_dependencies_are_installed(
                warn=verbose or not quiet
            ):
                continue
            include_match = include.search(root_relative_path) if include else True
            if include_match:
                yield child


def wrap_stream_for_windows(
    f: io.TextIOWrapper,
) -> Union[io.TextIOWrapper, "colorama.AnsiToWin32"]:
    """
    Wrap stream with colorama's wrap_stream so colors are shown on Windows.

    If `colorama` is unavailable, the original stream is returned unmodified.
    Otherwise, the `wrap_stream()` function determines whether the stream needs
    to be wrapped for a Windows environment and will accordingly either return
    an `AnsiToWin32` wrapper or the original stream.
    """
    try:
        from colorama.initialise import wrap_stream
    except ImportError:
        return f
    else:
        # Set `strip=False` to avoid needing to modify test_express_diff_with_color.
        return wrap_stream(f, convert=None, strip=False, autoreset=False, wrap=True)

import itertools
import math
from collections.abc import Callable, Iterator, Sequence
from dataclasses import dataclass, field
from typing import NamedTuple, Optional, TypeVar, Union, cast

from black.brackets import COMMA_PRIORITY, DOT_PRIORITY, BracketTracker
from black.mode import Mode, Preview
from black.nodes import (
    BRACKETS,
    CLOSING_BRACKETS,
    OPENING_BRACKETS,
    STANDALONE_COMMENT,
    TEST_DESCENDANTS,
    child_towards,
    first_leaf,
    is_docstring,
    is_import,
    is_multiline_string,
    is_one_sequence_between,
    is_one_tuple,
    is_type_comment,
    is_type_ignore_comment,
    is_with_or_async_with_stmt,
    last_leaf,
    make_simple_prefix,
    replace_child,
    syms,
    whitespace,
)
from black.strings import str_width
from blib2to3.pgen2 import token
from blib2to3.pytree import Leaf, Node

# types
T = TypeVar("T")
Index = int
LeafID = int
LN = Union[Leaf, Node]


@dataclass
class Line:
    """Holds leaves and comments. Can be printed with `str(line)`."""

    mode: Mode = field(repr=False)
    depth: int = 0
    leaves: list[Leaf] = field(default_factory=list)
    # keys ordered like `leaves`
    comments: dict[LeafID, list[Leaf]] = field(default_factory=dict)
    bracket_tracker: BracketTracker = field(default_factory=BracketTracker)
    inside_brackets: bool = False
    should_split_rhs: bool = False
    magic_trailing_comma: Leaf | None = None
    _complex_subscript_cache: dict[LeafID, bool] = field(
        default_factory=dict, repr=False
    )

    def append(
        self, leaf: Leaf, preformatted: bool = False, track_bracket: bool = False
    ) -> None:
        """Add a new `leaf` to the end of the line.

        Unless `preformatted` is True, the `leaf` will receive a new consistent
        whitespace prefix and metadata applied by :class:`BracketTracker`.
        Trailing commas are maybe removed, unpacked for loop variables are
        demoted from being delimiters.

        Inline comments are put aside.
        """
        has_value = (
            leaf.type in BRACKETS
            # empty fstring and tstring middles must not be truncated
            or leaf.type in (token.FSTRING_MIDDLE, token.TSTRING_MIDDLE)
            or bool(leaf.value.strip())
        )
        if not has_value:
            return

        if leaf.type == token.COLON and self.is_class_paren_empty:
            del self.leaves[-2:]
        if self.leaves and not preformatted:
            # Note: at this point leaf.prefix should be empty except for
            # imports, for which we only preserve newlines.
            leaf.prefix += whitespace(
                leaf,
                complex_subscript=self.is_complex_subscript(leaf),
                mode=self.mode,
            )
        if self.inside_brackets or not preformatted or track_bracket:
            self.bracket_tracker.mark(leaf)
            if self.mode.magic_trailing_comma:
                if self.has_magic_trailing_comma(leaf):
                    self.magic_trailing_comma = leaf
            elif self.has_magic_trailing_comma(leaf) and not (
                # A one-element tuple's trailing comma is syntactically required,
                # not magic, so it must never be removed. This is normally caught
                # by has_magic_trailing_comma, but that check misses the tuple
                # when its opening bracket was split onto an earlier line (for
                # example by a standalone comment inside the tuple), so verify
                # against the tree here before dropping the comma.
                leaf.parent is not None
                and is_one_tuple(leaf.parent)
            ):
                self.remove_trailing_comma()
        if not self.append_comment(leaf):
            self.leaves.append(leaf)

    def append_safe(self, leaf: Leaf, preformatted: bool = False) -> None:
        """Like :func:`append()` but disallow invalid standalone comment structure.

        Raises ValueError when any `leaf` is appended after a standalone comment
        or when a standalone comment is not the first leaf on the line.
        """
        if (
            self.bracket_tracker.depth == 0
            or self.bracket_tracker.any_open_for_or_lambda()
        ):
            if self.is_comment:
                raise ValueError("cannot append to standalone comments")

            if self.leaves and leaf.type == STANDALONE_COMMENT:
                raise ValueError(
                    "cannot append standalone comments to a populated line"
                )

        self.append(leaf, preformatted=preformatted)

    @property
    def is_comment(self) -> bool:
        """Is this line a standalone comment?"""
        return len(self.leaves) == 1 and self.leaves[0].type == STANDALONE_COMMENT

    @property
    def is_decorator(self) -> bool:
        """Is this line a decorator?"""
        return bool(self) and self.leaves[0].type == token.AT

    @property
    def is_import(self) -> bool:
        """Is this an import line?"""
        return bool(self) and is_import(self.leaves[0])

    @property
    def is_with_or_async_with_stmt(self) -> bool:
        """Is this a with_stmt line?"""
        return bool(self) and is_with_or_async_with_stmt(self.leaves[0])

    @property
    def is_class(self) -> bool:
        """Is this line a class definition?"""
        return (
            bool(self)
            and self.leaves[0].type == token.NAME
            and self.leaves[0].value == "class"
        )

    @property
    def is_stub_class(self) -> bool:
        """Is this line a class definition with a body consisting only of "..."?"""
        return self.is_class and self.leaves[-3:] == [
            Leaf(token.DOT, ".") for _ in range(3)
        ]

    @property
    def is_def(self) -> bool:
        """Is this a function definition? (Also returns True for async defs.)"""
        try:
            first_leaf = self.leaves[0]
        except IndexError:
            return False

        try:
            second_leaf: Leaf | None = self.leaves[1]
        except IndexError:
            second_leaf = None
        return (first_leaf.type == token.NAME and first_leaf.value == "def") or (
            first_leaf.type == token.ASYNC
            and second_leaf is not None
            and second_leaf.type == token.NAME
            and second_leaf.value == "def"
        )

    @property
    def is_stub_def(self) -> bool:
        """Is this line a function definition with a body consisting only of "..."?"""
        return self.is_def and self.leaves[-4:] == [Leaf(token.COLON, ":")] + [
            Leaf(token.DOT, ".") for _ in range(3)
        ]

    @property
    def is_class_paren_empty(self) -> bool:
        """Is this a class with no base classes but using parentheses?

        Those are unnecessary and should be removed.
        """
        return (
            bool(self)
            and len(self.leaves) == 4
            and self.is_class
            and self.leaves[2].type == token.LPAR
            and self.leaves[2].value == "("
            and self.leaves[3].type == token.RPAR
            and self.leaves[3].value == ")"
        )

    @property
    def _is_triple_quoted_string(self) -> bool:
        """Is the line a triple quoted string?"""
        if not self or self.leaves[0].type != token.STRING:
            return False
        value = self.leaves[0].value
        if value.startswith(('"""', "'''")):
            return True
        if value.startswith(("r'''", 'r"""', "R'''", 'R"""')):
            return True
        return False

    @property
    def is_docstring(self) -> bool:
        """Is the line a docstring?"""
        return bool(self) and is_docstring(self.leaves[0])

    @property
    def is_chained_assignment(self) -> bool:
        """Is the line a chained assignment"""
        return [leaf.type for leaf in self.leaves].count(token.EQUAL) > 1

    @property
    def opens_block(self) -> bool:
        """Does this line open a new level of indentation."""
        if len(self.leaves) == 0:
            return False
        return self.leaves[-1].type == token.COLON

    def is_fmt_pass_converted(
        self, *, first_leaf_matches: Callable[[Leaf], bool] | None = None
    ) -> bool:
        """Is this line converted from fmt off/skip code?

        If first_leaf_matches is not None, it only returns True if the first
        leaf of converted code matches.
        """
        if len(self.leaves) != 1:
            return False
        leaf = self.leaves[0]
        if (
            leaf.type != STANDALONE_COMMENT
            or leaf.fmt_pass_converted_first_leaf is None
        ):
            return False
        return first_leaf_matches is None or first_leaf_matches(
            leaf.fmt_pass_converted_first_leaf
        )

    def contains_standalone_comments(self) -> bool:
        """If so, needs to be split before emitting."""
        for leaf in self.leaves:
            if leaf.type == STANDALONE_COMMENT:
                return True

        return False

    def contains_implicit_multiline_string_with_comments(self) -> bool:
        """Check if we have an implicit multiline string with comments on the line"""
        for leaf_type, leaf_group_iterator in itertools.groupby(
            self.leaves, lambda leaf: leaf.type
        ):
            if leaf_type != token.STRING:
                continue
            leaf_list = list(leaf_group_iterator)
            if len(leaf_list) == 1:
                continue
            for leaf in leaf_list:
                if self.comments_after(leaf):
                    return True
        return False

    def contains_uncollapsable_type_comments(self) -> bool:
        ignored_ids = set()
        try:
            last_leaf = self.leaves[-1]
            ignored_ids.add(id(last_leaf))
            if last_leaf.type == token.COMMA or (
                last_leaf.type == token.RPAR and not last_leaf.value
            ):
                # When trailing commas or optional parens are inserted by Black for
                # consistency, comments after the previous last element are not moved
                # (they don't have to, rendering will still be correct).  So we ignore
                # trailing commas and invisible.
                last_leaf = self.leaves[-2]
                ignored_ids.add(id(last_leaf))
        except IndexError:
            return False

        # A type comment is uncollapsable if it is attached to a leaf
        # that isn't at the end of the line (since that could cause it
        # to get associated to a different argument) or if there are
        # comments before it (since that could cause it to get hidden
        # behind a comment.
        comment_seen = False
        for leaf_id, comments in self.comments.items():
            for comment in comments:
                if is_type_comment(comment, mode=self.mode):
                    if comment_seen or (
                        not is_type_ignore_comment(comment, mode=self.mode)
                        and leaf_id not in ignored_ids
                    ):
                        return True

                comment_seen = True

        return False

    def contains_unsplittable_type_ignore(self) -> bool:
        if not self.leaves:
            return False

        # If a 'type: ignore' is attached to the end of a line, we
        # can't split the line, because we can't know which of the
        # subexpressions the ignore was meant to apply to.
        #
        # We only want this to apply to actual physical lines from the
        # original source, though: we don't want the presence of a
        # 'type: ignore' at the end of a multiline expression to
        # justify pushing it all onto one line. Thus we
        # (unfortunately) need to check the actual source lines and
        # only report an unsplittable 'type: ignore' if this line was
        # one line in the original code.

        # Grab the first and last line numbers, skipping generated leaves
        first_line = next((leaf.lineno for leaf in self.leaves if leaf.lineno != 0), 0)
        last_line = next(
            (leaf.lineno for leaf in reversed(self.leaves) if leaf.lineno != 0), 0
        )

        if first_line == last_line:
            # We look at the last two leaves since a comma or an
            # invisible paren could have been added at the end of the
            # line.
            for node in self.leaves[-2:]:
                for comment in self.comments.get(id(node), []):
                    if is_type_ignore_comment(comment, mode=self.mode):
                        return True

        return False

    def contains_multiline_strings(self) -> bool:
        return any(is_multiline_string(leaf) for leaf in self.leaves)

    def has_magic_trailing_comma(self, closing: Leaf) -> bool:
        """Return True if we have a magic trailing comma, that is when:
        - there's a trailing comma here
        - it's not from single-element square bracket indexing
        - it's not a one-tuple
        """
        if not (
            closing.type in CLOSING_BRACKETS
            and self.leaves
            and self.leaves[-1].type == token.COMMA
        ):
            return False

        if closing.type == token.RBRACE:
            return True

        if closing.type == token.RSQB:
            if (
                closing.parent is not None
                and closing.parent.type == syms.trailer
                and closing.opening_bracket is not None
                and is_one_sequence_between(
                    closing.opening_bracket,
                    closing,
                    self.leaves,
                    brackets=(token.LSQB, token.RSQB),
                )
            ):
                assert closing.prev_sibling is not None
                assert closing.prev_sibling.type == syms.subscriptlist
                return False

            return True

        if self.is_import:
            return True

        if closing.opening_bracket is not None and not is_one_sequence_between(
            closing.opening_bracket, closing, self.leaves
        ):
            return True

        return False

    def append_comment(self, comment: Leaf) -> bool:
        """Add an inline or standalone comment to the line."""
        if (
            comment.type == STANDALONE_COMMENT
            and self.bracket_tracker.any_open_brackets()
        ):
            comment.prefix = ""
            return False

        if comment.type != token.COMMENT:
            return False

        if not self.leaves:
            comment.type = STANDALONE_COMMENT
            comment.prefix = ""
            return False

        last_leaf = self.leaves[-1]
        if (
            last_leaf.type == token.RPAR
            and not last_leaf.value
            and last_leaf.parent
            and len(list(last_leaf.parent.leaves())) <= 3
            and not is_type_comment(comment, mode=self.mode)
        ):
            # Comments on an optional parens wrapping a single leaf should belong to
            # the wrapped node except if it's a type comment. Pinning the comment like
            # this avoids unstable formatting caused by comment migration.
            if len(self.leaves) < 2:
                comment.type = STANDALONE_COMMENT
                comment.prefix = ""
                return False

            last_leaf = self.leaves[-2]
        self.comments.setdefault(id(last_leaf), []).append(comment)
        return True

    def comments_after(self, leaf: Leaf) -> list[Leaf]:
        """Generate comments that should appear directly after `leaf`."""
        return self.comments.get(id(leaf), [])

    def remove_trailing_comma(self) -> None:
        """Remove the trailing comma and moves the comments attached to it."""
        trailing_comma = self.leaves.pop()
        trailing_comma_comments = self.comments.pop(id(trailing_comma), [])
        self.comments.setdefault(id(self.leaves[-1]), []).extend(
            trailing_comma_comments
        )

    def is_complex_subscript(self, leaf: Leaf) -> bool:
        """Return True iff `leaf` is part of a slice with non-trivial exprs."""
        open_lsqb = self.bracket_tracker.get_open_lsqb()
        if open_lsqb is None:
            return False

        subscript_start = open_lsqb.next_sibling

        if isinstance(subscript_start, Node):
            if subscript_start.type == syms.listmaker:
                return False

            if subscript_start.type == syms.subscriptlist:
                subscript_start = child_towards(subscript_start, leaf)

        if subscript_start is None:
            return False

        # The pre_order walk only depends on subscript_start, which is stable
        # while a line is built, so cache it per node. Without this, appending
        # every leaf of a large bracketed expression that holds no TEST_DESCENDANTS
        # node (e.g. a long run of implicitly concatenated strings) re-walks the
        # whole subtree each time, which is quadratic.
        key = id(subscript_start)
        cached = self._complex_subscript_cache.get(key)
        if cached is None:
            cached = any(
                n.type in TEST_DESCENDANTS for n in subscript_start.pre_order()
            )
            self._complex_subscript_cache[key] = cached
        return cached

    def enumerate_with_length(
        self, is_reversed: bool = False
    ) -> Iterator[tuple[Index, Leaf, int]]:
        """Return an enumeration of leaves with their length.

        Stops prematurely on multiline strings and standalone comments.
        """
        op = cast(
            Callable[[Sequence[Leaf]], Iterator[tuple[Index, Leaf]]],
            enumerate_reversed if is_reversed else enumerate,
        )
        for index, leaf in op(self.leaves):
            length = len(leaf.prefix) + len(leaf.value)
            if "\n" in leaf.value:
                return  # Multiline strings, we can't continue.

            for comment in self.comments_after(leaf):
                length += len(comment.value)

            yield index, leaf, length

    def clone(self) -> "Line":
        return Line(
            mode=self.mode,
            depth=self.depth,
            inside_brackets=self.inside_brackets,
            should_split_rhs=self.should_split_rhs,
            magic_trailing_comma=self.magic_trailing_comma,
        )

    def __str__(self) -> str:
        """Render the line."""
        if not self:
            return "\n"

        indent = "    " * self.depth
        leaves = iter(self.leaves)
        first = next(leaves)
        res = f"{first.prefix}{indent}{first.value}"
        res += "".join(str(leaf) for leaf in leaves)
        comments_iter = itertools.chain.from_iterable(self.comments.values())
        comments = [str(comment) for comment in comments_iter]
        res += "".join(comments)

        return res + "\n"

    def __bool__(self) -> bool:
        """Return True if the line has leaves or comments."""
        return bool(self.leaves or self.comments)


@dataclass
class RHSResult:
    """Intermediate split result from a right hand split."""

    head: Line
    body: Line
    tail: Line
    opening_bracket: Leaf
    closing_bracket: Leaf


@dataclass
class LinesBlock:
    """Class that holds information about a block of formatted lines.

    This is introduced so that the EmptyLineTracker can look behind the standalone
    comments and adjust their empty lines for class or def lines.
    """

    mode: Mode
    previous_block: Optional["LinesBlock"]
    original_line: Line
    before: int = 0
    content_lines: list[str] = field(default_factory=list)
    after: int = 0
    form_feed: bool = False

    def all_lines(self) -> list[str]:
        empty_line = str(Line(mode=self.mode))
        prefix = make_simple_prefix(self.before, self.form_feed, empty_line)
        return [prefix] + self.content_lines + [empty_line * self.after]


_WHITESPACE_TOKENS = (
    token.NEWLINE,
    token.NL,
    token.INDENT,
    token.DEDENT,
    token.COMMENT,
    token.ENDMARKER,
)


class _DecoratedFuncInfo(NamedTuple):
    """Tracks the most recently seen decorated function for overload grouping."""

    name: str
    depth: int
    is_multi: bool


@dataclass
class EmptyLineTracker:
    """Provides a stateful method that returns the number of potential extra
    empty lines needed before and after the currently processed line.

    Note: this tracker works on lines that haven't been split yet.  It assumes
    the prefix of the first leaf consists of optional newlines.  Those newlines
    are consumed by `maybe_empty_lines()` and included in the computation.
    """

    mode: Mode
    previous_line: Line | None = None
    previous_block: LinesBlock | None = None
    previous_defs: list[Line] = field(default_factory=list)
    semantic_leading_comment: LinesBlock | None = None
    _pyi_previous_decorated_func: _DecoratedFuncInfo | None = None

    @staticmethod
    def _get_funcdef_name(node: Node | Leaf) -> str | None:
        """Extract the function name from a funcdef or async_funcdef node."""
        funcdef: Node | Leaf = node
        if isinstance(node, Node) and node.type == syms.async_funcdef:
            for sub in node.children:
                if sub.type == syms.funcdef:
                    funcdef = sub
                    break
        if not isinstance(funcdef, Node) or funcdef.type != syms.funcdef:
            return None
        # Grammar: funcdef = 'def' NAME parameters ':' ...
        name_node = funcdef.children[1]
        assert isinstance(name_node, Leaf)
        return name_node.value

    @staticmethod
    def _decorated_node_has_func_named(node: Node, name: str) -> bool:
        """Check if a ``decorated`` node contains a function with the given name."""
        return any(
            sub.type in (syms.funcdef, syms.async_funcdef)
            and EmptyLineTracker._get_funcdef_name(sub) == name
            for sub in node.children
        )

    @staticmethod
    def _find_adjacent_decorated(
        node: Node | Leaf, *, reverse: bool = False
    ) -> Node | None:
        """Walk siblings skipping whitespace tokens, returning the first
        ``decorated`` node found or ``None``."""
        sibling = node.prev_sibling if reverse else node.next_sibling
        while sibling is not None:
            if sibling.type == syms.decorated:
                assert isinstance(sibling, Node)
                return sibling
            elif sibling.type in _WHITESPACE_TOKENS:
                sibling = sibling.prev_sibling if reverse else sibling.next_sibling
            else:
                return None
        return None

    @staticmethod
    def _get_suite_first_decorated_funcname(suite: Node) -> str | None:
        """Return the function name of the first decorated function in a suite."""
        for child in suite.children:
            if isinstance(child, Node) and child.type == syms.decorated:
                for sub in child.children:
                    if sub.type in (syms.funcdef, syms.async_funcdef):
                        return EmptyLineTracker._get_funcdef_name(sub)
                break
            if child.type not in (token.NEWLINE, token.NL, token.INDENT, token.DEDENT):
                break
        return None

    @staticmethod
    def _if_stmt_branch_has_func_named(
        if_stmt: Node, exclude_suite: Node, name: str
    ) -> bool:
        """Check if any branch of an ``if_stmt`` (other than *exclude_suite*)
        contains a decorated function with the given *name*."""
        for child in if_stmt.children:
            if not isinstance(child, Node):
                continue
            if child.type != syms.suite:
                continue
            if child is exclude_suite:
                continue
            for stmt in child.children:
                if not isinstance(stmt, Node):
                    continue
                if stmt.type != syms.decorated:
                    continue
                if EmptyLineTracker._decorated_node_has_func_named(stmt, name):
                    return True
                break
        return False

    @staticmethod
    def _get_def_name(line: Line) -> str | None:
        """Extract the function name from a line that is a function definition."""
        if not line.is_def or not line.leaves:
            return None
        if line.leaves[0].value == "def":
            return line.leaves[1].value
        # async def: leaves = ['async', 'def', NAME, ...]
        return line.leaves[2].value

    @staticmethod
    def _is_line_decorated(line: Line) -> bool:
        """Check if a def line is part of a decorated statement."""
        if not line.is_def or not line.leaves:
            return False
        return EmptyLineTracker._find_decorated_node(line) is not None

    @staticmethod
    def _find_decorated_node(line: Line) -> Node | None:
        """Walk up from the first leaf of a line to its ``decorated`` node."""
        if not line.leaves:
            return None
        node = line.leaves[0].parent
        while node is not None:
            if node.type == syms.decorated:
                assert isinstance(node, Node)
                return node
            if node.type in (syms.suite, syms.file_input):
                return None
            node = node.parent
        return None

    @staticmethod
    def _get_decorator_target_name(line: Line) -> str | None:
        """For a decorator line, extract the name of the function it decorates.

        Only handles decorated functions, not decorated classes.
        """
        if not line.is_decorator:
            return None
        decorated = EmptyLineTracker._find_decorated_node(line)
        if decorated is None:
            return None
        for child in decorated.children:
            if child.type in (syms.funcdef, syms.async_funcdef):
                return EmptyLineTracker._get_funcdef_name(child)
        return None

    @staticmethod
    def _decorator_decorates_class(line: Line) -> bool:
        """Check if a decorator line decorates a class definition."""
        if not line.is_decorator:
            return False
        decorated = EmptyLineTracker._find_decorated_node(line)
        if decorated is None:
            return False
        return any(child.type == syms.classdef for child in decorated.children)

    @staticmethod
    def _def_is_followed_by_same_name_decorated_func(
        line: Line, *, include_conditional_blocks: bool = False
    ) -> bool:
        """Check if a decorated function is followed by a same-name decorated func.

        If *include_conditional_blocks* is true, the next decorated function may
        be inside an adjacent conditional block.
        """
        name = EmptyLineTracker._get_def_name(line)
        decorated = EmptyLineTracker._find_decorated_node(line)
        if name is None or decorated is None:
            return False

        sibling = decorated.next_sibling
        while sibling is not None and sibling.type in _WHITESPACE_TOKENS:
            sibling = sibling.next_sibling

        if sibling is None or not isinstance(sibling, Node):
            return False
        if sibling.type == syms.decorated:
            return EmptyLineTracker._decorated_node_has_func_named(sibling, name)
        if not include_conditional_blocks or sibling.type != syms.if_stmt:
            return False
        for child in sibling.children:
            if not isinstance(child, Node):
                continue
            if child.type != syms.suite:
                continue
            first_decorated_funcname = (
                EmptyLineTracker._get_suite_first_decorated_funcname(child)
            )
            return first_decorated_funcname == name
        return False

    def _is_in_current_group(self, current_line: Line) -> bool:
        """Check if current_line belongs to the same overload group being tracked."""
        prev = self._pyi_previous_decorated_func
        if prev is None:
            return False
        cur_name = (
            self._get_decorator_target_name(current_line)
            if current_line.is_decorator
            else self._get_def_name(current_line)
        )
        return (
            cur_name is not None
            and cur_name == prev.name
            and prev.depth == current_line.depth
            and (current_line.is_decorator or self._is_line_decorated(current_line))
        )

    @staticmethod
    def _decorated_node_starts_group(decorated_node: Node) -> bool:
        """Check if a `decorated` AST node is the first in a multi-function group.

        Returns True when the next statement-level sibling is also a decorated
        function with the same name.
        """
        name = None
        for child in decorated_node.children:
            if child.type in (syms.funcdef, syms.async_funcdef):
                name = EmptyLineTracker._get_funcdef_name(child)
                break
        if name is None:
            return False
        adjacent = EmptyLineTracker._find_adjacent_decorated(decorated_node)
        return adjacent is not None and EmptyLineTracker._decorated_node_has_func_named(
            adjacent, name
        )

    @staticmethod
    def _is_start_of_decorated_group(line: Line) -> bool:
        """Check if a decorator line starts a multi-function group.

        A multi-function group is 2+ consecutive decorated functions sharing the
        same name (e.g. @overload groups, @property + setter pairs).
        """
        if not line.is_decorator:
            return False
        decorated_node = EmptyLineTracker._find_decorated_node(line)
        if decorated_node is None or decorated_node.parent is None:
            return False
        return EmptyLineTracker._decorated_node_starts_group(decorated_node)

    @staticmethod
    def _get_block_first_decorated_funcname(line: Line) -> str | None:
        """Return the function name of the first decorated function in a block.

        *line* must be a block-opening line (ending with ``:``) such as
        ``if ...:``.  Returns ``None`` when the block doesn't start with a
        decorated function.
        """
        if not line.leaves or line.leaves[-1].type != token.COLON:
            return None
        suite = line.leaves[-1].next_sibling
        if suite is None or not isinstance(suite, Node) or suite.type != syms.suite:
            return None
        return EmptyLineTracker._get_suite_first_decorated_funcname(suite)

    @staticmethod
    def _block_is_part_of_overload_group(line: Line) -> bool:
        """Check if a block-opening line contains a decorated function that is
        part of a larger overload group — either because the ``if_stmt``'s next
        sibling is a same-name decorated function, or because another branch of
        the same ``if_stmt`` has one.
        """
        func_name = EmptyLineTracker._get_block_first_decorated_funcname(line)
        if func_name is None:
            return False

        suite = line.leaves[-1].next_sibling
        if suite is None or not isinstance(suite, Node):
            return False
        if_stmt = suite.parent
        if if_stmt is None or not isinstance(if_stmt, Node):
            return False

        # Check if the if_stmt's next sibling is a same-name decorated function.
        adjacent = EmptyLineTracker._find_adjacent_decorated(if_stmt)
        if adjacent is not None and EmptyLineTracker._decorated_node_has_func_named(
            adjacent, func_name
        ):
            return True

        # Check other branches (elif/else) of the same if_stmt.
        return EmptyLineTracker._if_stmt_branch_has_func_named(
            if_stmt, suite, func_name
        )

    @staticmethod
    def _is_decorator_in_conditional_overload(line: Line) -> bool:
        """Check if a decorator is inside an if/else block that is part of a
        broader overload group (a sibling or another branch of the same
        ``if_stmt`` contains a same-name decorated function)."""
        name = EmptyLineTracker._get_decorator_target_name(line)
        if name is None:
            return False

        decorated = EmptyLineTracker._find_decorated_node(line)
        if decorated is None:
            return False

        suite = decorated.parent
        if suite is None or suite.type != syms.suite:
            return False

        if_stmt = suite.parent
        if if_stmt is None or if_stmt.type != syms.if_stmt:
            return False

        # Check if_stmt's adjacent siblings for same-name decorated function.
        for reverse in (True, False):
            adjacent = EmptyLineTracker._find_adjacent_decorated(
                if_stmt, reverse=reverse
            )
            if (
                adjacent is not None
                and EmptyLineTracker._decorated_node_has_func_named(adjacent, name)
            ):
                return True

        # Check other branches of the same if_stmt.
        return EmptyLineTracker._if_stmt_branch_has_func_named(if_stmt, suite, name)

    def maybe_empty_lines(self, current_line: Line) -> LinesBlock:
        """Return the number of extra empty lines before and after the `current_line`.

        This is for separating `def`, `async def` and `class` with extra empty
        lines (two on module-level).
        """
        form_feed = (
            current_line.depth == 0
            and bool(current_line.leaves)
            and "\f\n" in current_line.leaves[0].prefix
        )
        before, after = self._maybe_empty_lines(current_line)
        previous_after = self.previous_block.after if self.previous_block else 0
        before = max(0, before - previous_after)

        # Always have one empty line after a module docstring
        if self._line_is_module_docstring(current_line):
            before = 1

        block = LinesBlock(
            mode=self.mode,
            previous_block=self.previous_block,
            original_line=current_line,
            before=before,
            after=after,
            form_feed=form_feed,
        )

        # Maintain the semantic_leading_comment state.
        if current_line.is_comment:
            if self.previous_line is None or (
                not self.previous_line.is_decorator
                # `or before` means this comment already has an empty line before
                and (not self.previous_line.is_comment or before)
                and (self.semantic_leading_comment is None or before)
            ):
                self.semantic_leading_comment = block
        # `or before` means this decorator already has an empty line before
        elif not current_line.is_decorator or before:
            self.semantic_leading_comment = None

        # Maintain _pyi_previous_decorated_func state for overload groups.
        # The tuple is (name, depth, is_multi) where is_multi indicates
        # the group has 2+ same-name decorated functions.
        overload_groups = (
            self.mode.is_pyi and Preview.pyi_overload_group_blank_lines in self.mode
        )
        if overload_groups:
            if current_line.is_def and self._is_line_decorated(current_line):
                name = self._get_def_name(current_line)
                if name is not None:
                    prev = self._pyi_previous_decorated_func
                    is_multi = (
                        prev is not None
                        and prev.name == name
                        and prev.depth == current_line.depth
                    )
                    self._pyi_previous_decorated_func = _DecoratedFuncInfo(
                        name=name,
                        depth=current_line.depth,
                        is_multi=is_multi
                        or (prev is not None and prev.name == name and prev.is_multi),
                    )
            elif (
                not current_line.is_decorator
                and not current_line.is_comment
                and (
                    self._pyi_previous_decorated_func is None
                    or (
                        current_line.depth <= self._pyi_previous_decorated_func.depth
                        # Don't reset on else/elif — they continue an if/else
                        # chain that may contain overloads at a deeper depth.
                        and not (
                            current_line.leaves
                            and current_line.leaves[0].value in ("else", "elif")
                        )
                    )
                )
            ):
                # Only reset when we see a non-decorator line at the same or
                # lower depth.  Body lines (docstrings, ...) at deeper depth
                # should not clear the state.
                self._pyi_previous_decorated_func = None

        self.previous_line = current_line
        self.previous_block = block
        return block

    def _line_is_module_docstring(self, current_line: Line) -> bool:
        previous_block = self.previous_block
        if not previous_block:
            return False
        if (
            len(previous_block.original_line.leaves) != 1
            or not previous_block.original_line.is_docstring
            or current_line.is_class
            or current_line.is_def
        ):
            return False
        while previous_block := previous_block.previous_block:
            if not previous_block.original_line.is_comment:
                return False
        return True

    def _maybe_empty_lines(self, current_line: Line) -> tuple[int, int]:
        max_allowed = 1
        if current_line.depth == 0:
            max_allowed = 1 if self.mode.is_pyi else 2
        overload_groups = (
            self.mode.is_pyi and Preview.pyi_overload_group_blank_lines in self.mode
        )

        if current_line.leaves:
            # Consume the first leaf's extra newlines.
            first_leaf = current_line.leaves[0]
            before = first_leaf.prefix.count("\n")
            before = min(before, max_allowed)
            first_leaf.prefix = ""
        else:
            before = 0

        user_had_newline = bool(before)
        depth = current_line.depth

        # Mutate self.previous_defs, remainder of this function should be pure
        previous_def = None
        while self.previous_defs and self.previous_defs[-1].depth >= depth:
            previous_def = self.previous_defs.pop()
        if current_line.is_def or current_line.is_class:
            self.previous_defs.append(current_line)

        if self.previous_line is None:
            # Don't insert empty lines before the first line in the file.
            return 0, 0

        if current_line.is_docstring:
            if self.previous_line.is_class:
                return 0, 1
            if self.previous_line.opens_block and self.previous_line.is_def:
                return 0, 0

        if previous_def is not None:
            assert self.previous_line is not None
            # Note: for decorator/def/class lines, `before` computed here is
            # passed to _maybe_empty_lines_for_class_or_def which may override
            # it. This block still matters for non-decorator/def/class lines
            # (e.g. a `var: int` statement following an overload group).
            if self.mode.is_pyi:
                if previous_def.is_class and not previous_def.is_stub_class:
                    before = 1
                elif (
                    overload_groups
                    and self._pyi_previous_decorated_func is not None
                    and self._pyi_previous_decorated_func.is_multi
                    and not current_line.is_comment
                    and self.previous_line.depth >= current_line.depth
                    and not (
                        current_line.leaves
                        and current_line.leaves[0].value in ("else", "elif")
                    )
                ):
                    if self._is_in_current_group(current_line):
                        before = 0
                    elif current_line.opens_block and (
                        self._get_block_first_decorated_funcname(current_line)
                        == self._pyi_previous_decorated_func.name
                    ):
                        before = 0
                    else:
                        before = 1
                elif (
                    overload_groups
                    and current_line.opens_block
                    and current_line.leaves
                    and current_line.leaves[0].value in ("else", "elif")
                    and self._block_is_part_of_overload_group(current_line)
                ):
                    # else/elif continuing a conditional overload group:
                    # don't insert a blank line above.
                    before = 0
                elif (
                    Preview.pyi_blank_line_after_function_docstring in self.mode
                    and previous_def.is_def
                    and self.previous_line.is_docstring
                    and self.previous_line.depth == previous_def.depth + 1
                    and not self._def_is_followed_by_same_name_decorated_func(
                        previous_def,
                        include_conditional_blocks=overload_groups,
                    )
                ):
                    before = 1
                elif depth and not current_line.is_def and self.previous_line.is_def:
                    if (
                        overload_groups
                        and current_line.opens_block
                        and self.previous_line.depth <= current_line.depth
                        and self._block_is_part_of_overload_group(current_line)
                    ):
                        before = 1
                    else:
                        # Empty lines between attributes and methods should
                        # be preserved.
                        before = 1 if user_had_newline else 0
                elif (
                    overload_groups
                    and current_line.is_comment
                    and self._pyi_previous_decorated_func is not None
                    and self._pyi_previous_decorated_func.depth == current_line.depth
                ):
                    # Own-line comments after a decorated function in .pyi:
                    # preserve a single user blank line but never insert one.
                    # For non-overload cases the comment_to_add_newlines
                    # mechanism will retroactively add needed blank lines.
                    before = 1 if user_had_newline else 0
                elif depth:
                    before = 0
                else:
                    before = 1
            else:
                if depth:
                    before = 1
                elif (
                    not depth
                    and previous_def.depth
                    and current_line.leaves[-1].type == token.COLON
                    and (
                        current_line.leaves[0].value
                        not in ("with", "try", "for", "while", "if", "match")
                    )
                ):
                    # We shouldn't add two newlines between an indented function and
                    # a dependent non-indented clause. This is to avoid issues with
                    # conditional function definitions that are technically top-level
                    # and therefore get two trailing newlines, but look weird and
                    # inconsistent when they're followed by elif, else, etc. This is
                    # worse because these functions only get *one* preceding newline
                    # already.
                    before = 1
                else:
                    before = 2

        if current_line.is_decorator or current_line.is_def or current_line.is_class:
            return self._maybe_empty_lines_for_class_or_def(
                current_line, before, user_had_newline
            )

        if (
            Preview.fmt_off_class_blank_lines in self.mode
            and self.previous_line.is_import
            and self.previous_line.depth == 0
            and current_line.depth == 0
            and current_line.is_fmt_pass_converted(
                first_leaf_matches=lambda leaf: leaf.value == "class"
            )
        ):
            return 2, 0

        if (
            self.previous_line.is_import
            and self.previous_line.depth == 0
            and current_line.depth == 0
            and not current_line.is_import
            and not current_line.is_fmt_pass_converted(first_leaf_matches=is_import)
        ):
            return 1, 0

        if (
            self.previous_line.is_import
            and not current_line.is_import
            and not current_line.is_fmt_pass_converted(first_leaf_matches=is_import)
            and depth == self.previous_line.depth
        ):
            return (before or 1), 0

        return before, 0

    def _maybe_empty_lines_for_class_or_def(
        self, current_line: Line, before: int, user_had_newline: bool
    ) -> tuple[int, int]:
        assert self.previous_line is not None
        overload_groups = (
            self.mode.is_pyi and Preview.pyi_overload_group_blank_lines in self.mode
        )

        if self.previous_line.is_decorator:
            if self.mode.is_pyi and current_line.is_stub_class:
                # Insert an empty line after a decorated stub class
                return 0, 1
            return 0, 0

        if self.previous_line.depth < current_line.depth and (
            self.previous_line.is_class or self.previous_line.is_def
        ):
            if self.mode.is_pyi:
                return 0, 0
            return 1 if user_had_newline else 0, 0

        comment_to_add_newlines: LinesBlock | None = None
        if (
            self.previous_line.is_comment
            and self.previous_line.depth == current_line.depth
            and before == 0
        ):
            slc = self.semantic_leading_comment
            if (
                slc is not None
                and slc.previous_block is not None
                and not slc.previous_block.original_line.is_class
                and not slc.previous_block.original_line.opens_block
                and slc.before <= 1
            ):
                comment_to_add_newlines = slc
            else:
                return 0, 0

        if self.mode.is_pyi:
            if current_line.is_class or self.previous_line.is_class:
                if self.previous_line.depth < current_line.depth:
                    newlines = 0
                elif self.previous_line.depth > current_line.depth:
                    newlines = 1
                elif current_line.is_stub_class and self.previous_line.is_stub_class:
                    # No blank line between classes with an empty body
                    newlines = 0
                else:
                    newlines = 1
            # Don't inspect only the previous line if it's part of the body of the
            # preceding statement. We always want a blank line after something with a
            # body.
            elif self.previous_line.depth > current_line.depth:
                if overload_groups and self._is_in_current_group(current_line):
                    newlines = 0
                else:
                    newlines = 1
            elif (
                overload_groups
                and self._pyi_previous_decorated_func is not None
                and self._pyi_previous_decorated_func.is_multi
                and self.previous_line.depth >= current_line.depth
            ):
                newlines = 0 if self._is_in_current_group(current_line) else 1
            elif overload_groups and self._is_in_current_group(current_line):
                # A comment between overloads may prevent is_multi from being
                # set, but _is_in_current_group still detects name continuity.
                newlines = 0
            elif (
                overload_groups
                and current_line.is_decorator
                and self.previous_line.depth >= current_line.depth
                and self._is_start_of_decorated_group(current_line)
                and (
                    self._pyi_previous_decorated_func is None
                    or (
                        self._pyi_previous_decorated_func.name
                        != self._get_decorator_target_name(current_line)
                    )
                    or self._pyi_previous_decorated_func.depth != current_line.depth
                )
            ):
                newlines = 1
            elif (
                current_line.is_def or current_line.is_decorator
            ) and not self.previous_line.is_def:
                if (
                    overload_groups
                    and current_line.is_decorator
                    and self.previous_line.is_comment
                    and self._is_decorator_in_conditional_overload(current_line)
                ):
                    # Comment before an overload inside a conditional block:
                    # remove blank lines between the comment and decorator.
                    newlines = 0
                elif current_line.depth:
                    # In classes empty lines between attributes and methods should
                    # be preserved.
                    newlines = min(1, before)
                else:
                    # Blank line between a block of functions (maybe with preceding
                    # decorators) and a block of non-functions
                    newlines = 1
            elif (
                Preview.pyi_blank_line_before_decorated_class in self.mode
                and current_line.is_decorator
                and self._decorator_decorates_class(current_line)
            ):
                newlines = 1
            else:
                newlines = 0
        else:
            newlines = 1 if current_line.depth else 2
            # If a user has left no space after a dummy implementation, don't insert
            # new lines. This is useful for instance for @overload or Protocols.
            if self.previous_line.is_stub_def and not user_had_newline:
                newlines = 0
        if comment_to_add_newlines is not None:
            previous_block = comment_to_add_newlines.previous_block
            if previous_block is not None:
                comment_to_add_newlines.before = (
                    max(comment_to_add_newlines.before, newlines) - previous_block.after
                )
                newlines = 0
        return newlines, 0


def enumerate_reversed(sequence: Sequence[T]) -> Iterator[tuple[Index, T]]:
    """Like `reversed(enumerate(sequence))` if that were possible."""
    index = len(sequence) - 1
    for element in reversed(sequence):
        yield (index, element)
        index -= 1


def append_leaves(
    new_line: Line, old_line: Line, leaves: list[Leaf], preformatted: bool = False
) -> None:
    """
    Append leaves (taken from @old_line) to @new_line, making sure to fix the
    underlying Node structure where appropriate.

    All of the leaves in @leaves are duplicated. The duplicates are then
    appended to @new_line and used to replace their originals in the underlying
    Node structure. Any comments attached to the old leaves are reattached to
    the new leaves.

    Pre-conditions:
        set(@leaves) is a subset of set(@old_line.leaves).
    """
    # @leaves is a slice of @old_line.leaves, so the leaves are in tree (DFS)
    # order and the children replaced within any one parent are reached at
    # strictly increasing positions. Remembering where the last child of each
    # parent was found lets the lookup resume from there instead of rescanning the
    # whole child list through Base.remove on every leaf, which is otherwise
    # O(n^2) when a node has many children replaced (e.g. wrapping the operand
    # tuple of "%s" % (a, b, c, ...) or copying a very long line for a second
    # formatting pass).
    search_start: dict[int, int] = {}
    for old_leaf in leaves:
        new_leaf = Leaf(old_leaf.type, old_leaf.value)
        parent = old_leaf.parent
        if parent is not None:
            children = parent.children
            index = search_start.get(id(parent), 0)
            while index < len(children) and children[index] is not old_leaf:
                index += 1
            if index < len(children):
                # set_child swaps the child in place (the old one keeps the same
                # position), so the next sibling to replace is always further on.
                parent.set_child(index, new_leaf)
                search_start[id(parent)] = index + 1
            else:
                # The resume hint missed (unexpected ordering); fall back to the
                # full scan so behaviour is unchanged.
                replace_child(old_leaf, new_leaf)
        new_line.append(new_leaf, preformatted=preformatted)

        for comment_leaf in old_line.comments_after(old_leaf):
            new_line.append(comment_leaf, preformatted=True)


def is_line_short_enough(line: Line, *, mode: Mode, line_str: str = "") -> bool:
    """For non-multiline strings, return True if `line` is no longer than `line_length`.
    For multiline strings, looks at the context around `line` to determine
    if it should be inlined or split up.
    Uses the provided `line_str` rendering, if any, otherwise computes a new one.
    """
    if not line_str:
        line_str = line_to_string(line)

    if line.contains_standalone_comments():
        return False
    if "\n" not in line_str:
        # No multiline strings (MLS) present
        return str_width(line_str) <= mode.line_length

    first, *_, last = line_str.split("\n")
    if str_width(first) > mode.line_length or str_width(last) > mode.line_length:
        return False

    # Traverse the AST to examine the context of the multiline string (MLS),
    # tracking aspects such as depth and comma existence,
    # to determine whether to split the MLS or keep it together.
    # Depth (which is based on the existing bracket_depth concept)
    # is needed to determine nesting level of the MLS.
    # Includes special case for trailing commas.
    commas: list[int] = []  # tracks number of commas per depth level
    multiline_string: Leaf | None = None
    # store the leaves that contain parts of the MLS
    multiline_string_contexts: list[LN] = []

    # `id()`s of the leaves on this line, used to find which ancestors of the
    # multiline string are rendered in full on this line (see below).
    line_leaf_ids = {id(leaf) for leaf in line.leaves}

    max_level_to_update: int | float = math.inf  # track the depth of the MLS
    for i, leaf in enumerate(line.leaves):
        if max_level_to_update == math.inf:
            had_comma: int | None = None
            if leaf.bracket_depth + 1 > len(commas):
                commas.append(0)
            elif leaf.bracket_depth + 1 < len(commas):
                had_comma = commas.pop()
            if (
                had_comma is not None
                and multiline_string is not None
                and multiline_string.bracket_depth == leaf.bracket_depth + 1
            ):
                # Have left the level with the MLS, stop tracking commas
                max_level_to_update = leaf.bracket_depth
                if had_comma > 0:
                    # MLS was in parens with at least one comma - force split
                    return False

        if leaf.bracket_depth <= max_level_to_update and leaf.type == token.COMMA:
            # Inside brackets, ignore trailing comma
            # directly after MLS/MLS-containing expression
            ignore_ctxs: list[LN | None] = [None]
            ignore_ctxs += multiline_string_contexts
            if (line.inside_brackets or leaf.bracket_depth > 0) and (
                i != len(line.leaves) - 1 or leaf.prev_sibling not in ignore_ctxs
            ):
                commas[leaf.bracket_depth] += 1
        if max_level_to_update != math.inf:
            max_level_to_update = min(max_level_to_update, leaf.bracket_depth)

        if is_multiline_string(leaf):
            if leaf.parent and (
                leaf.parent.type == syms.test
                or (leaf.parent.parent and leaf.parent.parent.type == syms.dictsetmaker)
            ):
                # Keep ternary and dictionary values parenthesized
                return False
            if len(multiline_string_contexts) > 0:
                # >1 multiline string cannot fit on a single line - force split
                return False
            multiline_string = leaf
            ctx: LN = leaf
            # fetch the leaf components of the MLS in the AST. An ancestor is
            # part of the MLS context while it is rendered in full on this line,
            # i.e. its first and last leaves both belong to the line (a line is
            # a contiguous run of leaves). Walking the leaf ids instead of
            # re-rendering `str(ctx)` and substring-searching `line_str` at every
            # level keeps this linear; the old form was quadratic on lines with a
            # large multiline-string-bearing collection (e.g. a dict literal with
            # many triple-quoted values).
            while (
                id(first_leaf(ctx)) in line_leaf_ids
                and id(last_leaf(ctx)) in line_leaf_ids
            ):
                multiline_string_contexts.append(ctx)
                if ctx.parent is None:
                    break
                ctx = ctx.parent

    # May not have a triple-quoted multiline string at all,
    # in case of a regular string with embedded newlines and line continuations
    if len(multiline_string_contexts) == 0:
        return True

    return all(val == 0 for val in commas)


def can_be_split(line: Line) -> bool:
    """Return False if the line cannot be split *for sure*.

    This is not an exhaustive search but a cheap heuristic that we can use to
    avoid some unfortunate formattings (mostly around wrapping unsplittable code
    in unnecessary parentheses).
    """
    leaves = line.leaves
    if len(leaves) < 2:
        return False

    if leaves[0].type == token.STRING and leaves[1].type == token.DOT:
        call_count = 0
        dot_count = 0
        next = leaves[-1]
        for leaf in leaves[-2::-1]:
            if leaf.type in OPENING_BRACKETS:
                if next.type not in CLOSING_BRACKETS:
                    return False

                call_count += 1
            elif leaf.type == token.DOT:
                dot_count += 1
            elif leaf.type == token.NAME:
                if not (next.type == token.DOT or next.type in OPENING_BRACKETS):
                    return False

            elif leaf.type not in CLOSING_BRACKETS:
                return False

            if dot_count > 1 and call_count > 1:
                return False

    return True


def _is_annotated_assignment(head: Line) -> bool:
    """Does `head` (an assignment's leaves up to the `=`) contain an annotation?

    Detects a `:` at the top bracket level, as in `x: dict[str, int] = ...`.
    Colons nested inside brackets (e.g. slices like `x[a:b]`) don't count.
    """
    depth = 0
    for leaf in head.leaves:
        if not leaf.value:
            continue
        if leaf.type in OPENING_BRACKETS:
            depth += 1
        elif leaf.type in CLOSING_BRACKETS:
            depth -= 1
        elif leaf.type == token.COLON and depth == 0:
            return True
    return False


def can_omit_invisible_parens(
    rhs: RHSResult,
    line_length: int,
    mode: Mode,
) -> bool:
    """Does `rhs.body` have a shape safe to reformat without optional parens around it?

    Returns True for only a subset of potentially nice looking formattings but
    the point is to not return false positives that end up producing lines that
    are too long.
    """
    line = rhs.body

    # Don't omit optional parens when the opening paren carries an inline comment.
    # Omitting them re-parents the comment onto a different leaf after the next
    # parse, which can make the RHS splitter choose a different shape on each
    # pass (unstable formatting / "different code on the second pass"). See
    # issues #3701, #3706, and #4384.
    if rhs.opening_bracket.type == token.LPAR and not rhs.opening_bracket.value:
        if rhs.head.comments.get(id(rhs.opening_bracket)):
            return False

    # We can't omit parens if doing so would result in a type: ignore comment
    # sharing a line with other comments, as that breaks type: ignore parsing.
    # Check if the opening bracket (last leaf of head) has comments that would merge
    # with comments from the first line of the body.
    if rhs.head.leaves:
        opening_bracket = rhs.head.leaves[-1]
        head_comments = rhs.head.comments.get(id(opening_bracket), [])

        # If there are comments on the opening bracket line, check if any would
        # conflict with type: ignore comments in the body
        if head_comments:
            has_type_ignore_in_head = any(
                is_type_ignore_comment(comment, mode=rhs.head.mode)
                for comment in head_comments
            )
            has_other_comment_in_head = any(
                not is_type_ignore_comment(comment, mode=rhs.head.mode)
                for comment in head_comments
            )

            # Check for comments in the body that would potentially end up on the
            # same line as the head comments when parens are removed
            has_type_ignore_in_body = False
            has_other_comment_in_body = False
            for leaf in rhs.body.leaves:
                for comment in rhs.body.comments.get(id(leaf), []):
                    if is_type_ignore_comment(comment, mode=rhs.body.mode):
                        has_type_ignore_in_body = True
                    else:
                        has_other_comment_in_body = True

            # Preserve parens if we have both type: ignore and other comments that
            # could end up on the same line
            if (has_type_ignore_in_head and has_other_comment_in_body) or (
                has_other_comment_in_head and has_type_ignore_in_body
            ):
                return False

    # We need optional parens in order to split standalone comments to their own lines
    # if there are no nested parens around the standalone comments
    closing_bracket: Leaf | None = None
    for leaf in reversed(line.leaves):
        if closing_bracket and leaf is closing_bracket.opening_bracket:
            closing_bracket = None
        if leaf.type == STANDALONE_COMMENT and not closing_bracket:
            return False
        if (
            not closing_bracket
            and leaf.type in CLOSING_BRACKETS
            and leaf.opening_bracket in line.leaves
            and leaf.value
        ):
            closing_bracket = leaf

    # For assignments to a subscripted target whose head is too long to fit
    # (e.g. `x[long_key][another_long_key] = expr`), the target must be split
    # at its subscript brackets no matter what, so optional parens around a
    # RHS that fits on the resulting tail line (`] = expr`) are unnecessary.
    # When the head fits on one line, paren-wrapping the RHS remains the
    # preferred style and this check must not fire. It must also come before
    # the delimiter_count > 1 early return below, which would otherwise
    # reject bodies with multiple delimiters such as `10 - 5`.
    if (
        Preview.fix_unnecessary_parens_in_indexed_assignment in mode
        and len(rhs.head.leaves) >= 3
        and rhs.head.leaves[-2].type == token.EQUAL
        # The target must actually end with a subscript: a visible `]`
        # immediately before the `=`. Invisible parens (e.g. around tuple
        # targets like `(x,) = ...`) have an empty value and don't count.
        and rhs.head.leaves[-3].type == token.RSQB
        and rhs.head.leaves[-3].value
        # In annotated assignments (`x: dict[str, int] = ...`) the `]` before
        # the `=` belongs to the annotation; splitting on the annotation's
        # brackets would be wrong, so leave the optional parens alone.
        and not _is_annotated_assignment(rhs.head)
        # The head must be too long to fit, forcing the subscript split.
        and not is_line_short_enough(rhs.head, mode=mode)
    ):
        # 4 extra characters for the `] = ` prefix on the tail line.
        tail_line_length = 4 * line.depth + 4
        for _index, _leaf, leaf_length in line.enumerate_with_length():
            tail_line_length += leaf_length
        if tail_line_length <= line_length:
            return True

    bt = line.bracket_tracker
    if not bt.delimiters:
        # Without delimiters the optional parentheses are useless.
        return True

    max_priority = bt.max_delimiter_priority()
    delimiter_count = bt.delimiter_count_with_priority(max_priority)
    if delimiter_count > 1:
        # With more than one delimiter of a kind the optional parentheses read better.
        return False

    if delimiter_count == 1:
        if max_priority == COMMA_PRIORITY and rhs.head.is_with_or_async_with_stmt:
            # For two context manager with statements, the optional parentheses read
            # better. In this case, `rhs.body` is the context managers part of
            # the with statement. `rhs.head` is the `with (` part on the previous
            # line.
            return False
        # Otherwise it may also read better, but we don't do it today and requires
        # careful considerations for all possible cases. See
        # https://github.com/psf/black/issues/2156.

    if max_priority == DOT_PRIORITY:
        # A single stranded method call doesn't require optional parentheses.
        return True

    assert len(line.leaves) >= 2, "Stranded delimiter"

    # With a single delimiter, omit if the expression starts or ends with
    # a bracket.
    first = line.leaves[0]
    second = line.leaves[1]
    if first.type in OPENING_BRACKETS and second.type not in CLOSING_BRACKETS:
        if _can_omit_opening_paren(line, first=first, line_length=line_length):
            return True

        # Note: we are not returning False here because a line might have *both*
        # a leading opening bracket and a trailing closing bracket.  If the
        # opening bracket doesn't match our rule, maybe the closing will.

    penultimate = line.leaves[-2]
    last = line.leaves[-1]

    if (
        last.type == token.RPAR
        or last.type == token.RBRACE
        or (
            # don't use indexing for omitting optional parentheses;
            # it looks weird
            last.type == token.RSQB
            and last.parent
            and last.parent.type != syms.trailer
        )
    ):
        if penultimate.type in OPENING_BRACKETS:
            # Empty brackets don't help.
            return False

        if is_multiline_string(first):
            # Additional wrapping of a multiline string in this situation is
            # unnecessary.
            return True

        if _can_omit_closing_paren(line, last=last, line_length=line_length):
            return True

    return False


def _can_omit_opening_paren(line: Line, *, first: Leaf, line_length: int) -> bool:
    """See `can_omit_invisible_parens`."""
    remainder = False
    length = 4 * line.depth
    _index = -1
    for _index, leaf, leaf_length in line.enumerate_with_length():
        if leaf.type in CLOSING_BRACKETS and leaf.opening_bracket is first:
            remainder = True
        if remainder:
            length += leaf_length
            if length > line_length:
                break

            if leaf.type in OPENING_BRACKETS:
                # There are brackets we can further split on.
                remainder = False

    else:
        # checked the entire string and line length wasn't exceeded
        if len(line.leaves) == _index + 1:
            return True

    return False


def _can_omit_closing_paren(line: Line, *, last: Leaf, line_length: int) -> bool:
    """See `can_omit_invisible_parens`."""
    length = 4 * line.depth
    seen_other_brackets = False
    for _index, leaf, leaf_length in line.enumerate_with_length():
        length += leaf_length
        if leaf is last.opening_bracket:
            if seen_other_brackets or length <= line_length:
                return True

        elif leaf.type in OPENING_BRACKETS:
            # There are brackets we can further split on.
            seen_other_brackets = True

    return False


def line_to_string(line: Line) -> str:
    """Returns the string representation of @line.

    WARNING: This is known to be computationally expensive.
    """
    return str(line).strip("\n")

"""
